const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>CardZero \u2014 Debt Snowball vs Avalanche Payoff Calculator</title>\n<meta name=\"description\" content=\"CardZero is a free debt snowball vs avalanche calculator that compares payoff strategies month by month. Handles 0% promo APR expiry, one-time windfalls, a smart hybrid plan, and skipped-payment tolerance. No signup.\">\n<meta name=\"keywords\" content=\"debt snowball vs avalanche calculator, credit card payoff planner, debt payoff calculator, debt snowball calculator, credit card debt payoff plan\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Which is better: the debt snowball or the debt avalanche?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Mathematically, the avalanche (highest interest rate first) almost always costs less in total interest. Behaviorally, the snowball (smallest balance first) delivers faster first wins, which helps many people stay consistent. CardZero shows both side by side with your real numbers so you can weigh the exact dollar difference against your own motivation style.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How does CardZero handle 0% promo APRs that expire?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Enter the promo rate and how many months it lasts on any debt. CardZero charges 0% (or your promo rate) during the promo window and automatically switches to the regular APR the month it expires. The Smart strategy even prioritizes debts whose promos expire soon so you can clear them before the rate jump.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Can I add a one-time extra payment, like a bonus or tax refund?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Yes. Add any number of windfall events in the payment plan section \u2014 just pick the month number and the amount. CardZero funnels each windfall into that month's extra-payment pool in your strategy's target order, and shows exactly how many months and how much interest it saves.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What happens if I skip my extra payments for a few months?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Use the skip-months control to model it honestly. CardZero pauses your extra payments (minimums still continue) for the months you choose, then recomputes your debt-free date and shows the added months and extra interest in a tolerance view \u2014 so a rough patch becomes a plan, not a guilt spiral.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Is CardZero really free to use?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Yes. Unlimited free usage with no signup, no paywall, and no watermark. All calculations run in your browser; your debt details are never sent to a server unless you choose to save a scenario locally on your own device.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How accurate is the payoff math?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"CardZero uses standard monthly interest accrual (APR divided by 12), the same method most card payoff calculators use. Real-world results can shift slightly with daily compounding, due-date timing, or rate changes, so treat the projection as accurate within about a month. It also assumes no new charges and on-time payments.\"\n      }\n    }\n  ]\n}\n</script>\n<style>\n  body { font-family: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; }\n  .num { font-variant-numeric: tabular-nums; }\n  .debt-input { width: 100%; border: 1px solid #d6d3c7; border-radius: 0.5rem; padding: 0.45rem 0.6rem; font-size: 0.875rem; background: #fff; }\n  .debt-input:focus { outline: 2px solid #14532D; border-color: #14532D; }\n  .chip { display: inline-flex; align-items: center; gap: 0.35rem; font-size: 0.75rem; font-weight: 600; padding: 0.3rem 0.7rem; border-radius: 9999px; }\n  .sched-wrap { max-height: 420px; overflow-y: auto; }\n  .sched-wrap::-webkit-scrollbar { width: 8px; }\n  .sched-wrap::-webkit-scrollbar-thumb { background: #14532D; border-radius: 4px; }\n  .sched-wrap::-webkit-scrollbar-track { background: #f0ecdc; }\n  input[type=\"number\"]::-webkit-inner-spin-button { opacity: 1; }\n  .strategy-tab { border-bottom: 3px solid transparent; }\n  .strategy-tab.active { border-bottom-color: #DC2626; color: #14532D; font-weight: 700; }\n  details.faq-item summary::-webkit-details-marker { display: none; }\n</style>\n</head>\n<body id=\"top\" class=\"bg-[#FEFCE8] text-slate-900 antialiased\">\n\n<!-- ============ STICKY HEADER ============ -->\n<header class=\"sticky top-0 z-50 bg-[#14532D] text-white shadow-md\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-14 flex items-center justify-between\">\n    <a href=\"#top\" class=\"text-xl font-extrabold tracking-tight\">Card<span class=\"text-[#f87171]\">Zero</span></a>\n    <nav class=\"text-sm font-semibold space-x-5\">\n      <a href=\"#top\" class=\"hover:text-amber-200 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:text-amber-200 transition\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ============ TOP AD (verbatim) ============ -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ HERO ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pt-8 pb-2\">\n  <div class=\"flex flex-wrap items-center gap-3\">\n    <span class=\"chip bg-[#14532D] text-white\">Unlimited Free Usage</span>\n    <span class=\"chip bg-white border border-[#14532D]/30 text-[#14532D]\">No signup &bull; No paywall &bull; No watermark</span>\n  </div>\n  <h1 class=\"mt-4 text-3xl sm:text-4xl font-extrabold text-[#14532D] tracking-tight\">Debt Snowball vs Avalanche, Decided by Your Numbers</h1>\n  <p class=\"mt-3 text-slate-700 max-w-3xl\">CardZero builds a month-by-month payoff plan for every debt you owe. Compare the snowball, avalanche, and a smart hybrid strategy side by side \u2014 with 0% promo-rate expiry, one-time windfalls, and honest math for the months life gets in the way.</p>\n</section>\n\n<!-- ============ TOOL ============ -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-6 space-y-6\">\n\n  <!-- STEP 1: debts -->\n  <section class=\"bg-white rounded-2xl shadow-sm border border-[#14532D]/15 p-4 sm:p-6\" aria-label=\"Your debts\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3\">\n      <h2 class=\"text-lg font-bold text-[#14532D]\"><span class=\"inline-flex items-center justify-center w-7 h-7 rounded-full bg-[#14532D] text-white text-sm mr-2\">1</span>Your debts</h2>\n      <div class=\"flex gap-2\">\n        <button id=\"btn-example\" class=\"text-xs font-semibold px-3 py-2 rounded-lg border border-[#14532D]/40 text-[#14532D] hover:bg-[#14532D] hover:text-white transition\">Load example</button>\n        <button id=\"btn-clear\" class=\"text-xs font-semibold px-3 py-2 rounded-lg border border-slate-300 text-slate-600 hover:bg-slate-100 transition\">Clear all</button>\n      </div>\n    </div>\n    <div class=\"overflow-x-auto mt-4\">\n      <table class=\"w-full min-w-[760px] text-sm\" id=\"debt-table\">\n        <thead>\n          <tr class=\"text-left text-xs uppercase tracking-wide text-slate-500\">\n            <th class=\"pb-2 pr-2\">Debt name</th>\n            <th class=\"pb-2 pr-2 w-28\">Balance ($)</th>\n            <th class=\"pb-2 pr-2 w-24\">APR (%)</th>\n            <th class=\"pb-2 pr-2 w-28\">Min. payment ($)</th>\n            <th class=\"pb-2 pr-2 w-24\">Promo APR (%) <span class=\"normal-case font-normal\">opt.</span></th>\n            <th class=\"pb-2 pr-2 w-24\">Promo months <span class=\"normal-case font-normal\">opt.</span></th>\n            <th class=\"pb-2 w-10\"></th>\n          </tr>\n        </thead>\n        <tbody id=\"debt-rows\"></tbody>\n      </table>\n    </div>\n    <button id=\"btn-add-debt\" class=\"mt-3 text-sm font-bold px-4 py-2 rounded-lg bg-[#14532D] text-white hover:bg-[#0e3d21] transition\">+ Add debt</button>\n    <p class=\"mt-2 text-xs text-slate-500\">Promo APR is for 0% balance-transfer or intro offers: enter the promo rate and how many months it lasts \u2014 the rate jumps back to the regular APR afterwards.</p>\n  </section>\n\n  <!-- STEP 2: payment plan -->\n  <section class=\"bg-white rounded-2xl shadow-sm border border-[#14532D]/15 p-4 sm:p-6\" aria-label=\"Payment plan\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\"><span class=\"inline-flex items-center justify-center w-7 h-7 rounded-full bg-[#14532D] text-white text-sm mr-2\">2</span>Your payment plan</h2>\n    <div class=\"grid sm:grid-cols-3 gap-4 mt-4\">\n      <div>\n        <label class=\"text-xs font-bold uppercase tracking-wide text-slate-500\" for=\"extra-input\">Extra payment every month ($)</label>\n        <input id=\"extra-input\" type=\"number\" min=\"0\" step=\"10\" value=\"350\" class=\"debt-input num mt-1\">\n      </div>\n      <div>\n        <label class=\"text-xs font-bold uppercase tracking-wide text-slate-500\" for=\"skip-input\">Skip extra payments for (months)</label>\n        <input id=\"skip-input\" type=\"number\" min=\"0\" max=\"24\" step=\"1\" value=\"0\" class=\"debt-input num mt-1\">\n        <p class=\"text-xs text-slate-500 mt-1\">Models a rough patch: minimums continue, extras pause.</p>\n      </div>\n      <div>\n        <label class=\"text-xs font-bold uppercase tracking-wide text-slate-500\">Start month</label>\n        <input id=\"start-input\" type=\"month\" class=\"debt-input mt-1\">\n      </div>\n    </div>\n\n    <div class=\"mt-5\">\n      <div class=\"flex flex-wrap items-center justify-between gap-2\">\n        <h3 class=\"text-sm font-bold text-[#14532D]\">Windfall events <span class=\"font-normal text-slate-500\">(one-time extra payments \u2014 bonus, tax refund, gift)</span></h3>\n        <button id=\"btn-add-windfall\" class=\"text-xs font-bold px-3 py-2 rounded-lg border border-[#DC2626]/50 text-[#DC2626] hover:bg-[#DC2626] hover:text-white transition\">+ Add windfall</button>\n      </div>\n      <div id=\"windfall-list\" class=\"mt-2 space-y-2\"></div>\n      <p id=\"windfall-empty\" class=\"text-xs text-slate-400 mt-2\">No windfalls yet. They are applied to that month's strategy target in full.</p>\n    </div>\n\n    <button id=\"btn-calc\" class=\"mt-5 w-full sm:w-auto text-base font-extrabold px-8 py-3 rounded-xl bg-[#DC2626] text-white hover:bg-[#b91c1c] transition shadow\">Calculate my payoff plan</button>\n    <p id=\"calc-error\" class=\"hidden mt-3 text-sm font-semibold text-[#DC2626]\"></p>\n  </section>\n\n  <!-- RESULTS: strategy comparison cards -->\n  <section id=\"results\" class=\"hidden\" aria-label=\"Strategy comparison\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\"><span class=\"inline-flex items-center justify-center w-7 h-7 rounded-full bg-[#14532D] text-white text-sm mr-2\">3</span>Strategy showdown</h2>\n    <div class=\"grid md:grid-cols-3 gap-4 mt-4\" id=\"strategy-cards\"></div>\n    <p class=\"mt-3 text-xs text-slate-500\" id=\"winner-note\"></p>\n  </section>\n\n  <!-- CHART -->\n  <section id=\"chart-section\" class=\"hidden bg-white rounded-2xl shadow-sm border border-[#14532D]/15 p-4 sm:p-6\" aria-label=\"Payoff timeline chart\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\">Payoff timeline \u2014 total balance over time</h2>\n    <div class=\"flex flex-wrap gap-4 mt-3 text-xs font-semibold\">\n      <span class=\"flex items-center gap-1.5\"><span class=\"inline-block w-4 h-1.5 rounded bg-[#C9A227]\"></span>Snowball</span>\n      <span class=\"flex items-center gap-1.5\"><span class=\"inline-block w-4 h-1.5 rounded bg-[#14532D]\"></span>Avalanche</span>\n      <span class=\"flex items-center gap-1.5\"><span class=\"inline-block w-4 h-1.5 rounded bg-[#DC2626]\"></span>Smart hybrid</span>\n    </div>\n    <div class=\"mt-2 overflow-x-auto\"><div class=\"min-w-[560px]\" id=\"chart\"></div></div>\n  </section>\n\n  <!-- SKIP TOLERANCE -->\n  <section id=\"tolerance-section\" class=\"hidden bg-white rounded-2xl shadow-sm border border-[#DC2626]/25 p-4 sm:p-6\" aria-label=\"Skipped-month tolerance\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\">Life happens: skipped-month tolerance</h2>\n    <p class=\"text-sm text-slate-600 mt-1\" id=\"tolerance-sub\"></p>\n    <div class=\"grid sm:grid-cols-2 gap-4 mt-4\">\n      <div class=\"rounded-xl bg-[#FEFCE8] border border-[#14532D]/20 p-4\">\n        <p class=\"text-xs font-bold uppercase tracking-wide text-slate-500\">On plan</p>\n        <p class=\"mt-1 text-2xl font-extrabold text-[#14532D] num\" id=\"tol-normal-months\"></p>\n        <p class=\"text-sm text-slate-600 num\" id=\"tol-normal-interest\"></p>\n      </div>\n      <div class=\"rounded-xl bg-red-50 border border-[#DC2626]/30 p-4\">\n        <p class=\"text-xs font-bold uppercase tracking-wide text-slate-500\" id=\"tol-skip-label\"></p>\n        <p class=\"mt-1 text-2xl font-extrabold text-[#DC2626] num\" id=\"tol-skip-months\"></p>\n        <p class=\"text-sm text-slate-600 num\" id=\"tol-skip-interest\"></p>\n      </div>\n    </div>\n    <div class=\"mt-4 flex flex-wrap gap-3 text-sm font-bold\">\n      <span class=\"chip bg-[#DC2626]/10 text-[#DC2626] border border-[#DC2626]/30\" id=\"tol-delta-months\"></span>\n      <span class=\"chip bg-[#DC2626]/10 text-[#DC2626] border border-[#DC2626]/30\" id=\"tol-delta-interest\"></span>\n    </div>\n    <p class=\"mt-3 text-xs text-slate-500\">This assumes minimums are still paid on time during the skipped months \u2014 only the extra payment pauses. Missing minimums is a different (and much costlier) story.</p>\n  </section>\n\n  <!-- SCHEDULE -->\n  <section id=\"schedule-section\" class=\"hidden bg-white rounded-2xl shadow-sm border border-[#14532D]/15 p-4 sm:p-6\" aria-label=\"Month-by-month schedule\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\">Month-by-month schedule</h2>\n    <div class=\"flex gap-4 mt-2 border-b border-slate-200 text-sm\" id=\"sched-tabs\">\n      <button data-tab=\"snowball\" class=\"strategy-tab pb-2 px-1 text-slate-500\">Snowball</button>\n      <button data-tab=\"avalanche\" class=\"strategy-tab pb-2 px-1 text-slate-500\">Avalanche</button>\n      <button data-tab=\"smart\" class=\"strategy-tab pb-2 px-1 text-slate-500\">Smart hybrid</button>\n    </div>\n    <div id=\"payoff-order\" class=\"mt-4\"></div>\n    <div class=\"sched-wrap mt-4 border border-slate-200 rounded-xl overflow-x-auto\">\n      <table class=\"w-full min-w-[640px] text-sm num\">\n        <thead class=\"bg-[#14532D] text-white text-xs uppercase tracking-wide sticky top-0\">\n          <tr>\n            <th class=\"text-left px-3 py-2\">Month</th>\n            <th class=\"text-left px-3 py-2\">Date</th>\n            <th class=\"text-right px-3 py-2\">Payment</th>\n            <th class=\"text-right px-3 py-2\">Principal</th>\n            <th class=\"text-right px-3 py-2\">Interest</th>\n            <th class=\"text-right px-3 py-2\">Balance</th>\n            <th class=\"text-left px-3 py-2\">Notes</th>\n          </tr>\n        </thead>\n        <tbody id=\"sched-body\"></tbody>\n      </table>\n    </div>\n    <button id=\"btn-toggle-sched\" class=\"mt-3 text-xs font-bold text-[#14532D] underline\"></button>\n    <div class=\"mt-4 flex flex-wrap gap-2\">\n      <button id=\"btn-csv\" class=\"text-xs font-bold px-4 py-2 rounded-lg bg-[#14532D] text-white hover:bg-[#0e3d21] transition\">Download schedule (CSV)</button>\n    </div>\n  </section>\n\n  <!-- SAVE -->\n  <section class=\"bg-white rounded-2xl shadow-sm border border-[#14532D]/15 p-4 sm:p-6\" aria-label=\"Save scenario\">\n    <h2 class=\"text-lg font-bold text-[#14532D]\">Save this scenario</h2>\n    <p class=\"text-xs text-slate-500 mt-1\">Stored only in this browser (localStorage) \u2014 nothing leaves your device.</p>\n    <div class=\"flex flex-wrap gap-2 mt-3\">\n      <input id=\"save-name\" type=\"text\" placeholder=\"Scenario name, e.g. Jan 2026 plan\" class=\"debt-input max-w-xs\" maxlength=\"40\">\n      <button id=\"btn-save\" class=\"text-sm font-bold px-4 py-2 rounded-lg bg-[#14532D] text-white hover:bg-[#0e3d21] transition\">Save</button>\n    </div>\n    <div id=\"saved-list\" class=\"mt-3 flex flex-wrap gap-2\"></div>\n  </section>\n\n</main>\n\n<!-- ============ BOTTOM AD (verbatim) ============ -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<script id=\"cardzero-core\">\n/* ============================================================\n * CardZero core payoff engine \u2014 pure functions, no DOM.\n * Shared by cardzero.html (inlined verbatim) and the Node tests.\n * Money values are plain numbers (dollars). APRs are percents.\n * ============================================================ */\n(function (root, factory) {\n  if (typeof module === 'object' && module && module.exports) {\n    module.exports = factory();\n  } else {\n    root.CardZero = factory();\n  }\n})(typeof self !== 'undefined' ? self : this, function () {\n  'use strict';\n\n  var EPS = 1e-9;\n  var MAX_MONTHS = 1200; // 100-year safety cap\n\n  function clamp(v, lo, hi) {\n    if (!isFinite(v)) return lo;\n    return Math.min(hi, Math.max(lo, v));\n  }\n\n  function toNum(v, fallback) {\n    var n = parseFloat(v);\n    return isFinite(n) ? n : fallback;\n  }\n\n  function r2(n) { // round to cents for display\n    return Math.round((n + Number.EPSILON) * 100) / 100;\n  }\n\n  /* ---------- input sanitizing ---------- */\n\n  function sanitizeDebt(raw, idx) {\n    var d = raw || {};\n    var i = (idx == null ? 0 : idx);\n    var promoAPR = parseFloat(d.promoAPR);\n    var promoMonths = Math.max(0, Math.floor(toNum(d.promoMonths, 0)));\n    var hasPromo = isFinite(promoAPR) && promoMonths > 0;\n    return {\n      id: 'd' + i,\n      name: (d.name != null && String(d.name).trim() !== '') ? String(d.name).trim().slice(0, 40) : ('Debt ' + (i + 1)),\n      balance: Math.max(0, toNum(d.balance, 0)),\n      apr: clamp(toNum(d.apr, 0), 0, 100),\n      minimum: Math.max(0, toNum(d.minimum, 0)),\n      promoAPR: hasPromo ? clamp(promoAPR, 0, 100) : NaN,\n      promoMonths: hasPromo ? promoMonths : 0\n    };\n  }\n\n  function sanitizeDebts(rawList) {\n    var out = [];\n    (rawList || []).forEach(function (d, i) {\n      var s = sanitizeDebt(d, i);\n      if (s.balance > EPS) out.push(s);\n    });\n    return out;\n  }\n\n  function sanitizeWindfalls(rawList) {\n    var out = [];\n    (rawList || []).forEach(function (w) {\n      var month = Math.floor(toNum(w && w.month, 0));\n      var amount = Math.max(0, toNum(w && w.amount, 0));\n      if (month >= 1 && amount > EPS) out.push({ month: month, amount: amount });\n    });\n    out.sort(function (a, b) { return a.month - b.month; });\n    return out;\n  }\n\n  /* ---------- rate model (differentiator #1: promo APR expiry) ---------- */\n\n  // month is 1-based (month 1 = first payment month)\n  function effectiveAPR(debt, month) {\n    if (isFinite(debt.promoAPR) && debt.promoMonths > 0 && month <= debt.promoMonths) {\n      return debt.promoAPR;\n    }\n    return debt.apr;\n  }\n\n  function monthsUntilPromoExpiry(debt, month) {\n    if (isFinite(debt.promoAPR) && debt.promoMonths > 0 && month <= debt.promoMonths) {\n      return debt.promoMonths - month + 1;\n    }\n    return Infinity;\n  }\n\n  /* ---------- strategy ordering ---------- */\n\n  // differentiator #3: \"smart\" = promo-deadline aware hybrid\n  // `active` items may be debt objects or simulation state wrappers {debt, balance, ...}\n  function strategyOrder(active, month, strategy) {\n    function D(x) { return (x && x.debt) || x; }\n    function rateOf(x) { return effectiveAPR(D(x), month); }\n    var list = active.slice();\n    if (strategy === 'snowball') {\n      list.sort(function (a, b) {\n        return (a.balance - b.balance) || (rateOf(b) - rateOf(a));\n      });\n    } else if (strategy === 'avalanche') {\n      list.sort(function (a, b) {\n        return (rateOf(b) - rateOf(a)) || (a.balance - b.balance);\n      });\n    } else { // 'smart'\n      list.sort(function (a, b) {\n        var ea = monthsUntilPromoExpiry(D(a), month);\n        var eb = monthsUntilPromoExpiry(D(b), month);\n        var au = ea <= 6, bu = eb <= 6; // promo expiring within 6 months = urgent\n        if (au && bu) {\n          var c = ea - eb;\n          if (c !== 0) return c;\n        } else if (au) return -1;\n        else if (bu) return 1;\n        return (rateOf(b) - rateOf(a)) || (a.balance - b.balance);\n      });\n    }\n    return list;\n  }\n\n  /* ---------- month-by-month payoff simulation ---------- */\n\n  // opts: { extra, strategy, windfalls:[{month,amount}], skipMonths, startYear, startMonth(1-12) }\n  function simulateDebts(rawDebts, opts) {\n    opts = opts || {};\n    var debts = sanitizeDebts(rawDebts);\n    var extra = Math.max(0, toNum(opts.extra, 0));\n    var windfalls = sanitizeWindfalls(opts.windfalls);\n    var skipMonths = Math.max(0, Math.floor(toNum(opts.skipMonths, 0)));\n    var strategy = opts.strategy === 'snowball' || opts.strategy === 'avalanche' ? opts.strategy : 'smart';\n    var startYear = Math.floor(toNum(opts.startYear, new Date().getFullYear()));\n    var startMonth = clamp(Math.floor(toNum(opts.startMonth, new Date().getMonth() + 1)), 1, 12);\n\n    var state = debts.map(function (d) {\n      return { debt: d, balance: d.balance, interestPaid: 0, totalPaid: 0, paidOffMonth: null };\n    });\n\n    var schedule = [];\n    var totalInterest = 0, totalPaid = 0;\n    var month = 0;\n    var finished = state.length === 0;\n\n    function active() {\n      return state.filter(function (s) { return s.balance > EPS && s.paidOffMonth === null; });\n    }\n\n    while (!finished && month < MAX_MONTHS) {\n      month++;\n      var cur = active();\n      if (cur.length === 0) { finished = true; break; }\n\n      var monthlyExtra = (month <= skipMonths) ? 0 : extra; // differentiator #4\n      var windfall = 0;\n      windfalls.forEach(function (w) { if (w.month === month) windfall += w.amount; });\n\n      // 1) interest accrual at the effective APR for this month\n      var monthInterest = 0;\n      cur.forEach(function (s) {\n        var rate = effectiveAPR(s.debt, month) / 100 / 12;\n        var interest = s.balance * rate;\n        s.balance += interest;\n        s.interestPaid += interest;\n        monthInterest += interest;\n        totalInterest += interest;\n      });\n\n      // 2) minimum payments\n      var monthPayment = 0;\n      cur.forEach(function (s) {\n        var pay = Math.min(s.balance, s.debt.minimum);\n        s.balance -= pay;\n        s.totalPaid += pay;\n        monthPayment += pay;\n        if (s.balance <= EPS) { s.balance = 0; s.paidOffMonth = month; }\n      });\n\n      // 3) extra + windfall pool -> strategy target(s), cascading same month (differentiator #2)\n      var pool = monthlyExtra + windfall;\n      var order = strategyOrder(active(), month, strategy);\n      var oi = 0;\n      while (pool > EPS && oi < order.length) {\n        var t = order[oi];\n        var pay = Math.min(t.balance, pool);\n        t.balance -= pay;\n        t.totalPaid += pay;\n        monthPayment += pay;\n        pool -= pay;\n        if (t.balance <= EPS) { t.balance = 0; t.paidOffMonth = month; oi++; }\n        else break;\n      }\n\n      totalPaid += monthPayment;\n\n      var remaining = state.reduce(function (a, s) { return a + s.balance; }, 0);\n      schedule.push({\n        month: month,\n        year: startYear + Math.floor((startMonth - 1 + month - 1) / 12),\n        calMonth: ((startMonth - 1 + month - 1) % 12) + 1,\n        payment: monthPayment,\n        principal: monthPayment - monthInterest,\n        interest: monthInterest,\n        extraUsed: monthlyExtra + windfall,\n        windfall: windfall,\n        balance: remaining,\n        perDebt: state.map(function (s) {\n          return { name: s.debt.name, payment: null, interest: null, balance: s.balance, apr: effectiveAPR(s.debt, month) };\n        })\n      });\n\n      if (active().length === 0) finished = true;\n    }\n\n    var payoffOrder = state\n      .filter(function (s) { return s.paidOffMonth !== null; })\n      .sort(function (a, b) { return a.paidOffMonth - b.paidOffMonth; })\n      .map(function (s) {\n        return { name: s.debt.name, month: s.paidOffMonth, interestPaid: s.interestPaid, totalPaid: s.totalPaid };\n      });\n\n    var lastRow = schedule[schedule.length - 1];\n    return {\n      strategy: strategy,\n      months: month,\n      finished: finished,\n      debtFreeYear: finished && lastRow ? lastRow.year : null,\n      debtFreeCalMonth: finished && lastRow ? lastRow.calMonth : null,\n      totalPaid: totalPaid,\n      totalInterest: totalInterest,\n      payoffOrder: payoffOrder,\n      schedule: schedule,\n      windfalls: windfalls,\n      skipMonths: skipMonths\n    };\n  }\n\n  /* ---------- comparisons ---------- */\n\n  function compareStrategies(rawDebts, opts) {\n    opts = opts || {};\n    var out = {};\n    ['snowball', 'avalanche', 'smart'].forEach(function (s) {\n      var o = {};\n      for (var k in opts) o[k] = opts[k];\n      o.strategy = s;\n      out[s] = simulateDebts(rawDebts, o);\n    });\n    // winner = lowest total interest among finished plans\n    var winner = null;\n    ['snowball', 'avalanche', 'smart'].forEach(function (s) {\n      if (out[s].finished && (!winner || out[s].totalInterest < out[winner].totalInterest - EPS)) winner = s;\n    });\n    out.winner = winner;\n    return out;\n  }\n\n  // differentiator #4: what happens if extra payments are skipped for K months\n  function skipTolerance(rawDebts, opts, skipMonths) {\n    var normal = simulateDebts(rawDebts, opts);\n    var o = {};\n    for (var k in opts) o[k] = opts[k];\n    o.skipMonths = skipMonths;\n    var skipped = simulateDebts(rawDebts, o);\n    return {\n      skipMonths: skipMonths,\n      normal: normal,\n      skipped: skipped,\n      extraMonths: skipped.finished && normal.finished ? skipped.months - normal.months : null,\n      extraInterest: skipped.finished && normal.finished ? skipped.totalInterest - normal.totalInterest : null\n    };\n  }\n\n  /* ---------- formatting ---------- */\n\n  var MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\n\n  function fmtMoney(n) {\n    var v = r2(n || 0);\n    return '$' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n  }\n\n  function fmtMoney0(n) {\n    var v = Math.round(n || 0);\n    return '$' + v.toLocaleString('en-US');\n  }\n\n  function fmtMonthYear(year, calMonth) {\n    if (!year || !calMonth) return '\u2014';\n    return MONTH_NAMES[calMonth - 1] + ' ' + year;\n  }\n\n  return {\n    EPS: EPS,\n    sanitizeDebt: sanitizeDebt,\n    sanitizeDebts: sanitizeDebts,\n    sanitizeWindfalls: sanitizeWindfalls,\n    effectiveAPR: effectiveAPR,\n    monthsUntilPromoExpiry: monthsUntilPromoExpiry,\n    strategyOrder: strategyOrder,\n    simulateDebts: simulateDebts,\n    compareStrategies: compareStrategies,\n    skipTolerance: skipTolerance,\n    fmtMoney: fmtMoney,\n    fmtMoney0: fmtMoney0,\n    fmtMonthYear: fmtMonthYear,\n    r2: r2\n  };\n});\n\n</script>\n<script>\n/* CardZero UI \u2014 reads debts, runs CardZero engine, renders results. */\n(function () {\n  'use strict';\n  var CZ = window.CardZero;\n  var $ = function (id) { return document.getElementById(id); };\n\n  var state = { debts: [], windfalls: [], lastResults: null, lastPlan: null, schedTab: 'smart', schedFull: false };\n  var STRAT_META = {\n    snowball: { name: 'Snowball', color: '#C9A227', desc: 'Smallest balance first \u2014 fast early wins, maximum motivation.' },\n    avalanche: { name: 'Avalanche', color: '#14532D', desc: 'Highest rate first \u2014 mathematically the cheapest payoff.' },\n    smart: { name: 'Smart Hybrid', color: '#DC2626', desc: 'Promo deadlines first, then highest rate \u2014 the best of both.' }\n  };\n\n  function defaultStartMonth() {\n    var d = new Date();\n    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');\n  }\n\n  function esc(s) {\n    return String(s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n\n  /* ---------- debt rows ---------- */\n\n  function renderDebtRows() {\n    var tb = $('debt-rows');\n    tb.innerHTML = '';\n    state.debts.forEach(function (d, i) {\n      var tr = document.createElement('tr');\n      tr.className = 'border-t border-slate-100';\n      tr.innerHTML =\n        '<td class=\"py-2 pr-2\"><input type=\"text\" class=\"debt-input\" data-f=\"name\" maxlength=\"40\" value=\"' + esc(d.name) + '\" placeholder=\"e.g. Store Card\"></td>' +\n        '<td class=\"py-2 pr-2\"><input type=\"number\" class=\"debt-input num\" data-f=\"balance\" min=\"0\" step=\"0.01\" value=\"' + d.balance + '\"></td>' +\n        '<td class=\"py-2 pr-2\"><input type=\"number\" class=\"debt-input num\" data-f=\"apr\" min=\"0\" max=\"100\" step=\"0.01\" value=\"' + d.apr + '\"></td>' +\n        '<td class=\"py-2 pr-2\"><input type=\"number\" class=\"debt-input num\" data-f=\"minimum\" min=\"0\" step=\"0.01\" value=\"' + d.minimum + '\"></td>' +\n        '<td class=\"py-2 pr-2\"><input type=\"number\" class=\"debt-input num\" data-f=\"promoAPR\" min=\"0\" max=\"100\" step=\"0.01\" placeholder=\"0\" value=\"' + (d.promoAPR === '' ? '' : d.promoAPR) + '\"></td>' +\n        '<td class=\"py-2 pr-2\"><input type=\"number\" class=\"debt-input num\" data-f=\"promoMonths\" min=\"0\" max=\"120\" step=\"1\" placeholder=\"12\" value=\"' + (d.promoMonths === '' ? '' : d.promoMonths) + '\"></td>' +\n        '<td class=\"py-2\"><button class=\"text-[#DC2626] font-bold text-lg leading-none px-2\" data-remove=\"' + i + '\" aria-label=\"Remove debt\">&times;</button></td>';\n      tb.appendChild(tr);\n    });\n    tb.querySelectorAll('input').forEach(function (inp) {\n      inp.addEventListener('input', function () {\n        var tr = inp.closest('tr');\n        var idx = Array.prototype.indexOf.call(tb.children, tr);\n        var f = inp.getAttribute('data-f');\n        state.debts[idx][f] = inp.value;\n        scheduleAutoCalc();\n      });\n    });\n    tb.querySelectorAll('[data-remove]').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        state.debts.splice(parseInt(btn.getAttribute('data-remove'), 10), 1);\n        renderDebtRows();\n        scheduleAutoCalc();\n      });\n    });\n  }\n\n  function blankDebt() {\n    return { name: '', balance: '', apr: '', minimum: '', promoAPR: '', promoMonths: '' };\n  }\n\n  function exampleDebts() {\n    return [\n      { name: 'Store Card', balance: 2400, apr: 24.99, minimum: 60, promoAPR: 0, promoMonths: 12 },\n      { name: 'Visa Card', balance: 5800, apr: 21.99, minimum: 145, promoAPR: '', promoMonths: '' },\n      { name: 'Personal Loan', balance: 3200, apr: 12.9, minimum: 95, promoAPR: '', promoMonths: '' }\n    ];\n  }\n\n  /* ---------- windfalls ---------- */\n\n  function renderWindfalls() {\n    var list = $('windfall-list');\n    list.innerHTML = '';\n    $('windfall-empty').style.display = state.windfalls.length ? 'none' : 'block';\n    state.windfalls.forEach(function (w, i) {\n      var div = document.createElement('div');\n      div.className = 'flex flex-wrap items-center gap-2 bg-[#FEFCE8] border border-[#14532D]/20 rounded-lg px-3 py-2';\n      div.innerHTML =\n        '<span class=\"text-xs font-bold text-[#14532D]\">Month</span>' +\n        '<input type=\"number\" class=\"debt-input num\" style=\"width:80px\" min=\"1\" max=\"600\" step=\"1\" value=\"' + w.month + '\" data-wf=\"month\">' +\n        '<span class=\"text-xs font-bold text-[#14532D]\">$</span>' +\n        '<input type=\"number\" class=\"debt-input num\" style=\"width:130px\" min=\"1\" step=\"1\" value=\"' + w.amount + '\" data-wf=\"amount\">' +\n        '<button class=\"text-[#DC2626] font-bold\" data-wf-remove=\"' + i + '\" aria-label=\"Remove windfall\">&times; remove</button>';\n      list.appendChild(div);\n    });\n    list.querySelectorAll('[data-wf]').forEach(function (inp) {\n      inp.addEventListener('input', function () {\n        var div = inp.closest('div');\n        var idx = Array.prototype.indexOf.call(list.children, div);\n        state.windfalls[idx][inp.getAttribute('data-wf')] = inp.value;\n        scheduleAutoCalc();\n      });\n    });\n    list.querySelectorAll('[data-wf-remove]').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        state.windfalls.splice(parseInt(btn.getAttribute('data-wf-remove'), 10), 1);\n        renderWindfalls();\n        scheduleAutoCalc();\n      });\n    });\n  }\n\n  /* ---------- calculation ---------- */\n\n  var autoTimer = null;\n  function scheduleAutoCalc() {\n    clearTimeout(autoTimer);\n    autoTimer = setTimeout(calculate, 600);\n  }\n\n  function readPlan() {\n    var debts = state.debts.map(function (d) {\n      return {\n        name: d.name, balance: d.balance, apr: d.apr, minimum: d.minimum,\n        promoAPR: d.promoAPR, promoMonths: d.promoMonths\n      };\n    }).filter(function (d) { return parseFloat(d.balance) > 0; });\n\n    var extra = parseFloat($('extra-input').value);\n    var skip = parseInt($('skip-input').value, 10);\n    var windfalls = state.windfalls.map(function (w) { return { month: w.month, amount: w.amount }; });\n\n    var startVal = $('start-input').value || defaultStartMonth();\n    var parts = startVal.split('-');\n    return {\n      debts: debts,\n      opts: {\n        extra: isFinite(extra) ? extra : 0,\n        skipMonths: isFinite(skip) ? Math.max(0, skip) : 0,\n        windfalls: windfalls,\n        startYear: parseInt(parts[0], 10),\n        startMonth: parseInt(parts[1], 10)\n      },\n      rawExtra: extra, rawSkip: skip\n    };\n  }\n\n  function showError(msg) {\n    var el = $('calc-error');\n    if (msg) { el.textContent = msg; el.classList.remove('hidden'); }\n    else el.classList.add('hidden');\n  }\n\n  function calculate() {\n    var plan = readPlan();\n    if (plan.debts.length === 0) {\n      showError('Add at least one debt with a balance above $0 to build your plan.');\n      return;\n    }\n    if (!isFinite(plan.rawExtra) || plan.rawExtra < 0) { showError('Extra monthly payment must be 0 or more.'); return; }\n    if (!isFinite(plan.rawSkip) || plan.rawSkip < 0) { showError('Skip months must be 0 or more.'); return; }\n    showError(null);\n\n    var res = CZ.compareStrategies(plan.debts, plan.opts);\n    state.lastResults = res;\n    state.lastPlan = plan;\n\n    // safety: if even minimums cannot dent the debt, flag it\n    var stuck = ['snowball', 'avalanche', 'smart'].some(function (s) { return !res[s].finished; });\n\n    renderStrategyCards(res, plan, stuck);\n    renderChart(res);\n    renderTolerance(plan);\n    renderScheduleTabs();\n    $('results').classList.remove('hidden');\n    $('chart-section').classList.remove('hidden');\n    $('schedule-section').classList.remove('hidden');\n    $('tolerance-section').classList.toggle('hidden', !plan.opts.skipMonths);\n    if (stuck) showError('Heads up: with these minimums, at least one strategy never pays the debt off (payments do not cover interest). Raise minimums or the extra payment.');\n  }\n\n  /* ---------- results rendering ---------- */\n\n  function monthsLabel(m) {\n    if (m < 12) return m + ' months';\n    var y = Math.floor(m / 12), r = m % 12;\n    return y + ' yr' + (y > 1 ? 's' : '') + (r ? ' ' + r + ' mo' : '');\n  }\n\n  function renderStrategyCards(res, plan, stuck) {\n    var wrap = $('strategy-cards');\n    wrap.innerHTML = '';\n    ['snowball', 'avalanche', 'smart'].forEach(function (s) {\n      var r = res[s], meta = STRAT_META[s];\n      var isWinner = res.winner === s;\n      var card = document.createElement('div');\n      card.className = 'rounded-2xl border-2 p-5 bg-white relative ' + (isWinner ? 'border-[#14532D] shadow-lg' : 'border-slate-200');\n      var first = r.payoffOrder.length ? r.payoffOrder[0] : null;\n      card.innerHTML =\n        (isWinner ? '<span class=\"absolute -top-3 left-4 chip bg-[#14532D] text-white\">BEST DEAL</span>' : '') +\n        '<div class=\"flex items-center gap-2\"><span class=\"inline-block w-3 h-3 rounded-full\" style=\"background:' + meta.color + '\"></span>' +\n        '<h3 class=\"font-extrabold text-lg text-slate-900\">' + meta.name + '</h3></div>' +\n        '<p class=\"text-xs text-slate-500 mt-1\">' + meta.desc + '</p>' +\n        (r.finished\n          ? '<div class=\"mt-4 space-y-2 text-sm\">' +\n            '<div class=\"flex justify-between\"><span class=\"text-slate-500\">Debt-free in</span><strong class=\"num\">' + monthsLabel(r.months) + '</strong></div>' +\n            '<div class=\"flex justify-between\"><span class=\"text-slate-500\">Debt-free date</span><strong class=\"num\">' + esc(CZ.fmtMonthYear(r.debtFreeYear, r.debtFreeCalMonth)) + '</strong></div>' +\n            '<div class=\"flex justify-between\"><span class=\"text-slate-500\">Total interest</span><strong class=\"num text-[#DC2626]\">' + CZ.fmtMoney(r.totalInterest) + '</strong></div>' +\n            '<div class=\"flex justify-between\"><span class=\"text-slate-500\">Total paid</span><strong class=\"num\">' + CZ.fmtMoney(r.totalPaid) + '</strong></div>' +\n            '<div class=\"flex justify-between\"><span class=\"text-slate-500\">First debt cleared</span><strong>' + (first ? esc(first.name) + ' <span class=\"num text-slate-500\">(mo ' + first.month + ')</span>' : '\u2014') + '</strong></div>' +\n            '</div>'\n          : '<p class=\"mt-4 text-sm font-bold text-[#DC2626]\">Never pays off \u2014 minimums do not cover the interest.</p>');\n      wrap.appendChild(card);\n    });\n\n    if (res.winner) {\n      var w = res.winner, worst = ['snowball', 'avalanche', 'smart'].reduce(function (a, s) {\n        return res[s].finished && res[s].totalInterest > res[a].totalInterest ? s : a;\n      }, 'snowball');\n      var save = res[worst].totalInterest - res[w].totalInterest;\n      $('winner-note').innerHTML = '<strong class=\"text-[#14532D]\">' + STRAT_META[w].name + '</strong> saves <strong class=\"text-[#DC2626] num\">' + CZ.fmtMoney(save) + '</strong> in interest vs ' + STRAT_META[worst].name.toLowerCase() + ' on your numbers.';\n    } else {\n      $('winner-note').textContent = '';\n    }\n  }\n\n  /* ---------- chart ---------- */\n\n  function renderChart(res) {\n    var keys = ['snowball', 'avalanche', 'smart'];\n    var series = keys.map(function (k) {\n      return { key: k, color: STRAT_META[k].color, pts: res[k].schedule.map(function (r) { return r.balance; }) };\n    });\n    var maxBal = Math.max.apply(null, series.map(function (s) { return s.pts[0] || 0; }).concat([1]));\n    var maxM = Math.max.apply(null, series.map(function (s) { return s.pts.length; }).concat([1]));\n    var W = 720, H = 260, padL = 58, padB = 28, padT = 10, padR = 10;\n    var iw = W - padL - padR, ih = H - padT - padB;\n    function X(i) { return padL + (maxM <= 1 ? 0 : (i / (maxM - 1)) * iw); }\n    function Y(v) { return padT + ih - (v / maxBal) * ih; }\n\n    var svg = '<svg viewBox=\"0 0 ' + W + ' ' + H + '\" class=\"w-full h-auto\" role=\"img\" aria-label=\"Balance over time chart\">';\n    // gridlines\n    for (var g = 0; g <= 4; g++) {\n      var gy = padT + (ih / 4) * g;\n      var gv = maxBal * (1 - g / 4);\n      svg += '<line x1=\"' + padL + '\" y1=\"' + gy + '\" x2=\"' + (W - padR) + '\" y2=\"' + gy + '\" stroke=\"#e7e2cf\" stroke-width=\"1\"/>';\n      svg += '<text x=\"' + (padL - 6) + '\" y=\"' + (gy + 4) + '\" text-anchor=\"end\" font-size=\"11\" fill=\"#78716c\">$' + shortNum(gv) + '</text>';\n    }\n    svg += '<text x=\"' + padL + '\" y=\"' + (H - 8) + '\" font-size=\"11\" fill=\"#78716c\">Month 1</text>';\n    svg += '<text x=\"' + (W - padR) + '\" y=\"' + (H - 8) + '\" text-anchor=\"end\" font-size=\"11\" fill=\"#78716c\">Month ' + maxM + '</text>';\n    series.forEach(function (s) {\n      if (!s.pts.length) return;\n      var d = s.pts.map(function (v, i) { return (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(v).toFixed(1); }).join(' ');\n      svg += '<path d=\"' + d + '\" fill=\"none\" stroke=\"' + s.color + '\" stroke-width=\"2.5\"/>';\n      var li = s.pts.length - 1;\n      svg += '<circle cx=\"' + X(li).toFixed(1) + '\" cy=\"' + Y(s.pts[li]).toFixed(1) + '\" r=\"4\" fill=\"' + s.color + '\"/>';\n    });\n    svg += '</svg>';\n    $('chart').innerHTML = svg;\n  }\n\n  function shortNum(v) {\n    if (v >= 1000) return (v / 1000).toFixed(v >= 10000 ? 0 : 1) + 'k';\n    return Math.round(v).toString();\n  }\n\n  /* ---------- tolerance ---------- */\n\n  function renderTolerance(plan) {\n    var k = plan.opts.skipMonths;\n    if (!k) return;\n    var baseOpts = {};\n    for (var key in plan.opts) baseOpts[key] = plan.opts[key];\n    baseOpts.skipMonths = 0;\n    var normal = CZ.compareStrategies(plan.debts, baseOpts);\n    // use the winner strategy's numbers for an apples-to-apples comparison\n    var wKey = normal.winner || 'smart';\n    var n = CZ.simulateDebts(plan.debts, Object.assign({}, baseOpts, { strategy: wKey }));\n    var s = CZ.simulateDebts(plan.debts, Object.assign({}, plan.opts, { strategy: wKey }));\n    $('tolerance-sub').textContent = 'Using the ' + STRAT_META[wKey].name.toLowerCase() + ' plan, what happens if you pause the extra $' + (plan.opts.extra) + '/month for the first ' + k + ' month' + (k > 1 ? 's' : '') + '?';\n    $('tol-skip-label').textContent = 'Skipping extras for ' + k + ' mo';\n    $('tol-normal-months').textContent = n.finished ? monthsLabel(n.months) + ' \u00b7 ' + CZ.fmtMonthYear(n.debtFreeYear, n.debtFreeCalMonth) : 'Never pays off';\n    $('tol-normal-interest').textContent = n.finished ? 'Interest: ' + CZ.fmtMoney(n.totalInterest) : '\u2014';\n    $('tol-skip-months').textContent = s.finished ? monthsLabel(s.months) + ' \u00b7 ' + CZ.fmtMonthYear(s.debtFreeYear, s.debtFreeCalMonth) : 'Never pays off';\n    $('tol-skip-interest').textContent = s.finished ? 'Interest: ' + CZ.fmtMoney(s.totalInterest) : '\u2014';\n    $('tol-delta-months').textContent = (s.finished && n.finished) ? '+' + (s.months - n.months) + ' months' : 'Plan breaks';\n    $('tol-delta-interest').textContent = (s.finished && n.finished) ? '+' + CZ.fmtMoney(s.totalInterest - n.totalInterest) + ' interest' : '';\n  }\n\n  /* ---------- schedule table ---------- */\n\n  function promoExpiryMonths(plan) {\n    // map month -> list of debt names whose promo expires that month\n    var map = {};\n    plan.debts.forEach(function (raw) {\n      var d = CZ.sanitizeDebt(raw, 0);\n      if (d.promoMonths > 0) {\n        map[d.promoMonths] = map[d.promoMonths] || [];\n        map[d.promoMonths].push(d.name);\n      }\n    });\n    return map;\n  }\n\n  function renderScheduleTabs() {\n    var tabs = $('sched-tabs').querySelectorAll('.strategy-tab');\n    tabs.forEach(function (t) {\n      t.classList.toggle('active', t.getAttribute('data-tab') === state.schedTab);\n      t.onclick = function () { state.schedTab = t.getAttribute('data-tab'); state.schedFull = false; renderScheduleTabs(); };\n    });\n    renderPayoffOrder();\n    renderSchedTable();\n  }\n\n  function renderPayoffOrder() {\n    var res = state.lastResults[state.schedTab];\n    var wrap = $('payoff-order');\n    if (!res.finished) { wrap.innerHTML = ''; return; }\n    wrap.innerHTML = '<p class=\"text-xs font-bold uppercase tracking-wide text-slate-500 mb-2\">Payoff order \u2014 ' + STRAT_META[state.schedTab].name + '</p>' +\n      '<div class=\"flex flex-wrap gap-2\">' +\n      res.payoffOrder.map(function (p, i) {\n        return '<span class=\"chip bg-[#14532D]/10 text-[#14532D] border border-[#14532D]/25\"><strong>' + (i + 1) + '</strong> ' + esc(p.name) +\n          ' <span class=\"num text-slate-500\">\u00b7 mo ' + p.month + '</span></span>';\n      }).join('') + '</div>';\n  }\n\n  function renderSchedTable() {\n    var res = state.lastResults[state.schedTab];\n    var plan = state.lastPlan;\n    var body = $('sched-body');\n    var expiry = promoExpiryMonths(plan);\n    var windByMonth = {};\n    res.windfalls.forEach(function (w) { windByMonth[w.month] = (windByMonth[w.month] || 0) + w.amount; });\n\n    var rows = res.schedule;\n    var shown = state.schedFull ? rows : rows.slice(0, 24);\n    var html = '';\n    shown.forEach(function (r) {\n      var notes = [];\n      if (windByMonth[r.month]) notes.push('<span class=\"chip bg-[#DC2626]/10 text-[#DC2626] border border-[#DC2626]/30\">windfall ' + CZ.fmtMoney0(windByMonth[r.month]) + '</span>');\n      if (expiry[r.month]) notes.push('<span class=\"chip bg-amber-100 text-amber-800 border border-amber-300\">promo ends: ' + esc(expiry[r.month].join(', ')) + '</span>');\n      html += '<tr class=\"border-t border-slate-100 ' + (r.month % 2 ? 'bg-white' : 'bg-[#FEFCE8]/60') + '\">' +\n        '<td class=\"px-3 py-2\">' + r.month + '</td>' +\n        '<td class=\"px-3 py-2\">' + CZ.fmtMonthYear(r.year, r.calMonth) + '</td>' +\n        '<td class=\"px-3 py-2 text-right font-semibold\">' + CZ.fmtMoney(r.payment) + '</td>' +\n        '<td class=\"px-3 py-2 text-right text-[#14532D]\">' + CZ.fmtMoney(r.principal) + '</td>' +\n        '<td class=\"px-3 py-2 text-right text-[#DC2626]\">' + CZ.fmtMoney(r.interest) + '</td>' +\n        '<td class=\"px-3 py-2 text-right font-semibold\">' + CZ.fmtMoney(r.balance) + '</td>' +\n        '<td class=\"px-3 py-2\">' + notes.join(' ') + '</td></tr>';\n    });\n    if (!state.schedFull && rows.length > 24) {\n      html += '<tr class=\"border-t border-slate-100\"><td colspan=\"7\" class=\"px-3 py-3 text-center text-xs text-slate-500\">\u2026 ' + (rows.length - 24) + ' more months \u2014 expand to see the full schedule \u2026</td></tr>';\n    }\n    body.innerHTML = html;\n    var btn = $('btn-toggle-sched');\n    if (rows.length > 24) {\n      btn.textContent = state.schedFull ? 'Show fewer months' : 'Show all ' + rows.length + ' months';\n      btn.style.display = '';\n    } else btn.style.display = 'none';\n  }\n\n  /* ---------- CSV ---------- */\n\n  function downloadCSV() {\n    var res = state.lastResults[state.schedTab];\n    if (!res) return;\n    var lines = ['Month,Date,Payment,Principal,Interest,Balance'];\n    res.schedule.forEach(function (r) {\n      lines.push([r.month, CZ.fmtMonthYear(r.year, r.calMonth), r.payment.toFixed(2), r.principal.toFixed(2), r.interest.toFixed(2), r.balance.toFixed(2)].join(','));\n    });\n    var blob = new Blob([lines.join('\\n')], { type: 'text/csv' });\n    var a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = 'cardzero-' + state.schedTab + '-schedule.csv';\n    document.body.appendChild(a);\n    a.click();\n    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);\n  }\n\n  /* ---------- localStorage ---------- */\n\n  var LS_KEY = 'cardzero-scenarios-v1';\n\n  function getSaved() {\n    try { return JSON.parse(localStorage.getItem(LS_KEY) || '[]'); } catch (e) { return []; }\n  }\n  function setSaved(list) {\n    try { localStorage.setItem(LS_KEY, JSON.stringify(list)); } catch (e) {}\n  }\n\n  function renderSaved() {\n    var wrap = $('saved-list');\n    wrap.innerHTML = '';\n    getSaved().forEach(function (sc, i) {\n      var chip = document.createElement('span');\n      chip.className = 'chip bg-white border border-[#14532D]/30 text-[#14532D]';\n      chip.innerHTML = esc(sc.name) + ' <button class=\"ml-1 font-bold text-[#DC2626]\" data-load=\"' + i + '\">load</button><button class=\"ml-1 font-bold text-slate-400\" data-del=\"' + i + '\" aria-label=\"Delete\">&times;</button>';\n      wrap.appendChild(chip);\n    });\n    wrap.querySelectorAll('[data-load]').forEach(function (b) {\n      b.addEventListener('click', function () {\n        var sc = getSaved()[parseInt(b.getAttribute('data-load'), 10)];\n        if (!sc) return;\n        state.debts = sc.debts.map(function (d) { return Object.assign(blankDebt(), d); });\n        state.windfalls = (sc.windfalls || []).map(function (w) { return { month: w.month, amount: w.amount }; });\n        $('extra-input').value = sc.extra;\n        $('skip-input').value = sc.skip || 0;\n        renderDebtRows(); renderWindfalls();\n        calculate();\n      });\n    });\n    wrap.querySelectorAll('[data-del]').forEach(function (b) {\n      b.addEventListener('click', function () {\n        var list = getSaved();\n        list.splice(parseInt(b.getAttribute('data-del'), 10), 1);\n        setSaved(list); renderSaved();\n      });\n    });\n  }\n\n  /* ---------- wire up ---------- */\n\n  function init() {\n    $('start-input').value = defaultStartMonth();\n    state.debts = exampleDebts().map(function (d) {\n      var b = blankDebt();\n      for (var k in d) b[k] = d[k];\n      return b;\n    });\n    state.windfalls = [{ month: 8, amount: 1000 }];\n    renderDebtRows();\n    renderWindfalls();\n    renderSaved();\n\n    $('btn-add-debt').addEventListener('click', function () { state.debts.push(blankDebt()); renderDebtRows(); });\n    $('btn-example').addEventListener('click', function () {\n      state.debts = exampleDebts().map(function (d) { var b = blankDebt(); for (var k in d) b[k] = d[k]; return b; });\n      state.windfalls = [{ month: 8, amount: 1000 }];\n      renderDebtRows(); renderWindfalls(); calculate();\n    });\n    $('btn-clear').addEventListener('click', function () { state.debts = []; state.windfalls = []; renderDebtRows(); renderWindfalls(); calculate(); });\n    $('btn-add-windfall').addEventListener('click', function () { state.windfalls.push({ month: 6, amount: 500 }); renderWindfalls(); scheduleAutoCalc(); });\n    ['extra-input', 'skip-input', 'start-input'].forEach(function (id) {\n      $(id).addEventListener('input', scheduleAutoCalc);\n    });\n    $('btn-calc').addEventListener('click', calculate);\n    $('btn-toggle-sched').addEventListener('click', function () { state.schedFull = !state.schedFull; renderSchedTable(); });\n    $('btn-csv').addEventListener('click', downloadCSV);\n    $('btn-save').addEventListener('click', function () {\n      var name = $('save-name').value.trim() || ('Scenario ' + (getSaved().length + 1));\n      var plan = readPlan();\n      var list = getSaved();\n      list.push({ name: name, debts: plan.debts, windfalls: plan.windfalls, extra: plan.opts.extra, skip: plan.opts.skipMonths });\n      setSaved(list); renderSaved();\n      $('save-name').value = '';\n    });\n\n    calculate();\n  }\n\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);\n  else init();\n})();\n\n</script>\n\n\n<!-- ============ SEO ARTICLE ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 py-10\">\n<article id=\"seo-article\" class=\"prose-article max-w-4xl mx-auto text-slate-800 leading-relaxed\">\n<h2 class=\"text-2xl sm:text-3xl font-extrabold text-[#14532D]\">Debt Snowball vs Avalanche: The Complete Guide to Paying Off Debt Faster</h2>\n\n<p class=\"mt-4\">There is a moment in almost every debt story when the minimum payments stop feeling like progress. The balances barely move, the interest charges show up like rent you never agreed to, and every month ends with the same uneasy arithmetic. That is the moment a real plan becomes worth more than motivation \u2014 and it is exactly what a <strong>debt payoff calculator</strong> is built for. Instead of guessing which card to attack first, you model your actual balances, rates, and budget, and you let the math show you the cheapest and fastest route to zero.</p>\n\n<p class=\"mt-4\">The two strategies every <strong>debt snowball vs avalanche calculator</strong> compares are simple to describe and surprisingly hard to choose between. The <strong>debt snowball</strong> method targets your smallest balance first. You pay every minimum, then throw all your extra money at the tiniest debt until it is gone. That freed-up payment rolls into the next-smallest debt, and the payments get bigger as the debts get fewer \u2014 like a snowball rolling downhill. The <strong>debt avalanche</strong> method works the same way except the target is your highest interest rate. You still pay every minimum and focus the extra on one account, but you pick the debt that is costing you the most per dollar, every dollar, every month.</p>\n\n<p class=\"mt-4\">Mathematically, the avalanche wins almost every time. Interest is just a price tag on borrowed money, and paying the highest price tag first minimizes the total interest you will ever pay. In a typical three-card scenario \u2014 say $2,400 at 25%, $5,800 at 22%, and $3,200 at 13% with $350 extra a month \u2014 the avalanche usually shaves several months and hundreds of dollars off the snowball's totals. The gap grows with the spread between your rates: debts clustered within a few percentage points of each other barely differ between methods, while a 25% card sitting next to a 10% loan makes the avalanche's advantage obvious. A good <strong>credit card payoff planner</strong> does not make you take this on faith; it runs both strategies on your real numbers and shows the exact dollar difference.</p>\n\n<p class=\"mt-4\">So why does the snowball exist at all? Because debt is not purely a math problem \u2014 it is a behavior problem that happens to involve numbers. Research on debt repayment has repeatedly found that people who close out entire accounts early are more likely to stay with the plan. The snowball gives you a win in month one or two: an account closed, a statement gone, a small ceremony of progress. The avalanche, by contrast, can feel like pouring money into a void for a year while your biggest balance barely bends. If you know yourself \u2014 if you have started budgets before and abandoned them by spring \u2014 the \"motivation tax\" of the snowball may be the cheapest option in practice, because the best strategy is the one you actually finish.</p>\n\n<p class=\"mt-4\">This is where the simple two-way comparison that most free calculators offer starts to feel incomplete, and where a more serious <strong>credit card debt payoff plan</strong> needs to handle the messy realities of actual credit cards. The first reality is the <strong>0% promotional APR</strong>. Balance-transfer cards and store cards love introductory offers: 0% for 12, 15, or 21 months, then the rate jumps to something like 22% overnight. During the promo window, that debt is effectively free money \u2014 every payment goes straight to principal. A naive avalanche calculator that only looks at the regular APR would attack the promo balance last, which is correct today but potentially disastrous if the promo expires with a big balance left and the rate suddenly becomes your highest. The right question is not \"what is the rate now?\" but \"what is the rate over the life of my plan?\" CardZero models promo expiry explicitly: you enter the promo rate and how many months it lasts, and the simulation charges the promo rate until the deadline and the regular APR after it.</p>\n\n<p class=\"mt-4\">The second reality is the <strong>windfall</strong> \u2014 the tax refund, the bonus, the sold furniture, the birthday money from a generous relative. Most calculators treat your payment as a flat monthly number forever, which means a $1,000 one-time payment has nowhere to go in the model. In real life, a windfall is one of the highest-leverage events in a debt plan: a lump sum applied to your current target does not just reduce that balance, it pulls every subsequent payoff date forward, because the freed-up payment starts rolling sooner. CardZero lets you schedule windfalls by month and funnels each one into that month's strategy target, cascading to the next debt if the target falls. Run the numbers once without the windfall and once with it \u2014 the difference in total interest is often the most motivating number on the page.</p>\n\n<p class=\"mt-4\">The third reality is that pure strategies are rarely optimal in practice, which is why CardZero includes a third option: the <strong>smart hybrid</strong>. It starts from a simple observation \u2014 a promo rate about to expire is a deadline, and deadlines beat percentages. The smart strategy first targets any debt whose promotional rate expires within six months, ordered by urgency, then falls back to avalanche ordering (highest effective rate first). This captures the snowball's psychological insight (kill the urgent, time-boxed threat first) and the avalanche's mathematical insight (then kill the most expensive remaining debt) without requiring you to switch strategies manually. For households juggling a balance transfer alongside regular cards, the hybrid routinely beats both pure strategies on total interest while still delivering an early win.</p>\n\n<p class=\"mt-4\">The fourth reality is the one nobody puts in a calculator and everybody lives through: <strong>life happens</strong>. The car needs brakes, the hours get cut, the holidays arrive. Extra payments get skipped. Most plans pretend this never occurs, so the first skipped month feels like failure and the plan gets abandoned. A better approach is to price the rough patch in advance. CardZero's skipped-month tolerance view pauses your extra payments for as many months as you choose \u2014 minimums still continue \u2014 and shows you the honest cost: how many extra months the plan takes, and how much extra interest the pause adds. Knowing that three skipped months cost you, say, four months and $180 of interest turns a vague fear into a concrete, survivable number. It also teaches the most important lesson of debt planning: minimums are sacred, extras are flexible, and a plan that survives contact with reality is better than a perfect plan you quit.</p>\n\n<p class=\"mt-4\">How should you actually use a tool like this? Start with honest inputs. Pull your latest statements \u2014 not your memory of them \u2014 and enter each balance, APR, and minimum payment exactly. Include every revolving debt: credit cards, store cards, lines of credit. Fixed-installment loans can be included too, though their minimums rarely change. Set your extra payment to a number you can sustain for at least six months, not the heroic number you could manage once. Then compare all three strategies and look at three outputs: the debt-free date, the total interest, and the month your first debt disappears. If the avalanche saves you $900 but your first win arrives in month 14, ask yourself honestly whether you will still be following the plan in month 8. There is no shame in choosing the snowball for behavioral reasons \u2014 a <strong>debt snowball calculator</strong> exists precisely because the human side of the equation matters.</p>\n\n<p class=\"mt-4\">A few practical tactics multiply whatever strategy you choose. First, <strong>stop adding new charges</strong> to the cards you are paying down; the simulation assumes no new borrowing, and new charges are the number-one reason real plans diverge from projected ones. Second, <strong>automate the minimums</strong> so a forgotten due date never triggers a late fee or penalty APR, which can instantly make your modeled rates fiction. Third, <strong>re-run the plan quarterly</strong>: rates change, balances move, and a promo you forgot about may be expiring. Fourth, if you take a balance-transfer offer, divide the transferred balance by the promo months and treat that as a non-negotiable monthly target \u2014 clearing it before expiry is almost always the highest-return move available. Fifth, keep a small emergency buffer before accelerating payments aggressively; every dollar sent to a card while you have zero savings is a dollar that the next surprise expense will force you to borrow back at full interest.</p>\n\n<p class=\"mt-4\">It is also worth understanding what the math assumes, so you can trust it appropriately. CardZero uses standard monthly interest accrual \u2014 each month's interest equals the balance times the APR divided by 12 \u2014 which is the same method the major free payoff calculators use. Real cards compound daily and your due dates will not align perfectly with calendar months, so treat the projected debt-free month as accurate within about a month, not to the day. The model also assumes minimum payments stay fixed; in reality, card minimums usually shrink as the balance falls, which means your actual payoff may arrive slightly later than projected if you only ever pay the true minimum. Paying a fixed total each month \u2014 the minimum plus your extra \u2014 is both simpler and faster.</p>\n\n<p class=\"mt-4\">Finally, a word about cost. Debt planning tools range from free calculators to paid apps with monthly subscriptions, and there is a quiet irony in paying a subscription to get out of debt. CardZero is free with unlimited usage, no account, and no watermark on anything you download, because the people who most need a payoff plan are the people least able to pay for one. Your numbers never leave your browser; scenarios you save are stored only on your own device. The goal is simple: give you the same month-by-month clarity that expensive tools offer, with the promo handling, windfall modeling, and skip tolerance they usually lack, so the plan you print or save is one you can actually follow to zero.</p>\n\n<p class=\"mt-4\">Debt freedom is rarely a single heroic decision. It is a few hundred ordinary payments, aimed at the right target, in the right order, with a plan that survives the months when life intervenes. Run your numbers, pick the strategy you will finish, and start this month \u2014 the cheapest interest is the interest you never pay.</p>\n</article>\n\n<!-- ============ FAQS ============ -->\n<section class=\"max-w-4xl mx-auto mt-12\" aria-label=\"Frequently asked questions\">\n<h2 class=\"text-2xl font-extrabold text-[#14532D]\">Frequently Asked Questions</h2>\n<div class=\"mt-6 space-y-3\" id=\"faq-list\">\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">Which is better: the debt snowball or the debt avalanche?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">Mathematically, the avalanche (highest interest rate first) almost always costs less in total interest. Behaviorally, the snowball (smallest balance first) delivers faster first wins, which helps many people stay consistent. CardZero shows both side by side with your real numbers so you can weigh the exact dollar difference against your own motivation style \u2014 and the Smart hybrid often beats both.</p>\n</details>\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">How does CardZero handle 0% promo APRs that expire?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">Enter the promo rate and how many months it lasts on any debt. CardZero charges the promo rate during the window and automatically switches to the regular APR the month it expires. The Smart strategy goes further: it prioritizes debts whose promos expire within six months, so you can clear them before the rate jumps.</p>\n</details>\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">Can I add a one-time extra payment, like a bonus or tax refund?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">Yes. Add any number of windfall events in the payment plan section \u2014 pick the month number and the amount. CardZero funnels each windfall into that month's extra-payment pool in your strategy's target order, cascading to the next debt if the target is fully paid, and shows exactly how many months and how much interest it saves.</p>\n</details>\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">What happens if I skip my extra payments for a few months?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">Use the skip-months control to model it honestly. CardZero pauses your extra payments (minimums still continue) for the months you choose, then recomputes your debt-free date and shows the added months and extra interest in a tolerance view \u2014 so a rough patch becomes a plan, not a guilt spiral.</p>\n</details>\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">Is CardZero really free to use?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">Yes. Unlimited free usage with no signup, no paywall, and no watermark. All calculations run in your browser; your debt details are never sent to a server. Scenarios you save are stored only in your own browser's local storage.</p>\n</details>\n\n<details class=\"faq-item bg-white rounded-xl border border-[#14532D]/15 px-5 py-4\">\n<summary class=\"font-bold text-[#14532D] cursor-pointer list-none flex justify-between items-center\">How accurate is the payoff math?<span class=\"text-[#DC2626] text-xl leading-none\">+</span></summary>\n<p class=\"mt-3 text-slate-700 text-sm leading-relaxed\">CardZero uses standard monthly interest accrual (APR divided by 12), the same method most card payoff calculators use. Real-world results can shift slightly with daily compounding, due-date timing, or rate changes, so treat the projection as accurate within about a month. It also assumes no new charges and on-time payments.</p>\n</details>\n\n</div>\n</section>\n</section>\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"bg-[#14532D] text-white mt-8\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-4\">\n    <p class=\"font-extrabold text-lg\">Card<span class=\"text-[#f87171]\">Zero</span></p>\n    <p class=\"text-xs text-white/70 text-center\">Free debt payoff planner. Educational estimates only \u2014 not financial advice.</p>\n    <nav class=\"text-sm font-semibold space-x-5\">\n      <a href=\"#top\" class=\"hover:text-amber-200 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:text-amber-200 transition\">More Tools</a>\n    </nav>\n  </div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n</body>\n</html>\n";
